const input = $input.first().json;
const body = input.body || input;
const text = String(body.message || body.task || body.request || '').toLowerCase();
const risky = /send|invite|schedule|commit|approve|delete|publish|external|discount|contract/.test(text);
const skill = body.skill || body.skill_id || 'auto_select_approved_skill';
return [{ json: {
  status: 'staging_ready',
  agent: 'Agentic Butler',
  contract_version: '2026-08-06.2',
  role: 'Top-level work execution agent. Skill Orchestrator is an internal Butler component, not a peer top-level agent.',
  selected_skill: skill,
  internal_components: ['skill_orchestrator', 'task_agents', 'tool_router', 'trace_writer'],
  approval_gate: { required: risky, reason: risky ? 'Request contains potentially external, destructive, or commitment-creating action.' : null },
  actor_checkpoint: { required: true, agent: 'Actor Twin', when: ['before_skill_selection', 'before_risky_action', 'after_result_draft'] },
  output_contract: { trace_required: true, structured_result_required: true, knowledge_candidate_allowed: true },
  received: body,
  next: 'Attach approved skill registry, task-agent calls, approval pause/resume, and trace storage.'
} }];

